import { t } from './i18n.mjs';
import {showUserSettings} from './user-settings.mjs';
let currentAccount={};
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cash=n=>new Intl.NumberFormat(t("en-US","vi-VN","ko-KR")).format(n)+' ₫';
const defaultBio='On my journey to be debt-free.';
const defaultNext='Đặt một mục tiêu nhỏ cho tháng này.';
const profileBio=()=>profile.bio===defaultBio?t(defaultBio,'Trên hành trình thoát nợ.','빚에서 벗어나는 여정에 있습니다.'):profile.bio;
const profileNext=()=>profile.next===defaultNext?t('Set a small goal for this month.',defaultNext,'이번 달에 이룰 작은 목표를 세우세요.'):profile.next;
let accountRole='Broke';let accountName='';let profile={name:'Your name',bio:defaultBio,goal:50000000,paid:0,next:defaultNext,thanks:''},tab='journey',api;
try{const p=JSON.parse(localStorage.getItem('debtfreelately-profile'));if(p&&typeof p.name==='string'&&Number.isFinite(p.goal)&&p.goal>0&&Number.isFinite(p.paid)&&p.paid>=0&&p.paid<=p.goal)profile={...profile,...p};}catch{}
function write(){try{localStorage.setItem('debtfreelately-profile',JSON.stringify(profile));}catch{api.toast(t("Could not save on this device. Changes will last for this session only.","Không lưu được trên thiết bị. Thay đổi chỉ tồn tại trong phiên này.","이 기기에 저장할 수 없습니다. 변경 사항은 이번 세션에만 적용됩니다."));}}
export function initBroke(callbacks){api=callbacks;const root=document.createElement('section');root.id='broke-dashboard';root.setAttribute('aria-label',t("Profile","Trang cá nhân","프로필"));document.body.append(root);root.addEventListener('keydown',event=>{const card=event.target.closest('[data-supporter-name]');if(card&&(event.key==='Enter'||event.key===' ')){event.preventDefault();card.click();}});root.addEventListener('click',ev=>{const supporter=ev.target.closest('[data-supporter-name]');if(supporter){api.supporterMessage({id:supporter.dataset.supporterName,name:supporter.dataset.supporterName,initials:supporter.dataset.supporterInitials,color:supporter.dataset.supporterColor});return;}const b=ev.target.closest('[data-broke]');if(!b)return;const action=b.dataset.broke;if(action==='settings'||action==='edit')showUserSettings(currentAccount,{modal:api.modal,close:api.close,toast:api.toast,logout:api.logout,onSave:updated=>{currentAccount=updated;accountName=updated.name;render();}});if(action==='goal')edit();if(action==='role')api.role();if(action==='create-card')api.createCard();if(action==='post')api.post();if(action==='posts'){document.body.classList.remove('broke-mode');api.posts();}if(action==='journey'||action==='activity'){tab=action;render();}if(action==='thanks')thanks();if(action==='supporters')supporters();if(action==='logout')api.logout();if(action==='saved')api.saved();if(action==='messages')api.messages();if(action==='discover'){document.body.classList.remove('broke-mode');api.discover();}if(action==='home')showBroke();});render();}
export function showBroke(account){if(account){currentAccount={...account};if(account.designPreview){try{currentAccount={...account,...JSON.parse(localStorage.getItem('debtfreelately-preview-settings')||'{}')};}catch{}}accountName=currentAccount.name;accountRole=account.role||'Broke';}document.body.classList.remove('onboarding');document.body.classList.add('broke-mode');render();window.scrollTo(0,0);document.querySelector('#broke-title')?.focus({preventScroll:true});}
export function hideBroke(){document.body.classList.remove('broke-mode');}
function render(){const root=document.querySelector('#broke-dashboard');if(!root)return;const posts=api?.getPosts()||[],pledged=posts.reduce((s,p)=>s+p.pledged,0),pct=Math.round(profile.paid/profile.goal*100);root.innerHTML=`<div class="broke-top"><a href="#" class="broke-brand" data-broke="home"><img src="assets/debtfreelately-logo-transparent.png" alt="DebtFreeLately"></a><nav class="broke-top-nav" aria-label="${t("Profile navigation","Điều hướng trang cá nhân","프로필 탐색")}"><a class="broke-management-link" href="/my-cards">${t("▤ Submitted cards","▤ Thẻ đã gửi","▤ 제출한 카드")}</a><button class="selected" data-broke="home">⌂ <span>${t("Home","Trang chủ","홈")}</span></button><button data-broke="discover">◈ <span>${t("Discover Broke","Tìm Broke","Broke 둘러보기")}</span></button><button data-broke="saved">☆ <span>${t("Saved","Đã lưu","저장됨")}</span></button><button data-broke="messages">✉ <span>${t("Messages","Tin nhắn","메시지")}</span></button><button type="button" data-notifications>♧ <span>${t("Notifications","Thông báo","알림")}</span></button>${currentAccount.isAdmin?'<a class="broke-management-link" href="/admin">'+t("Admin","Quản trị","관리")+'</a>':''}</nav></div><div class="broke-layout"><div class="broke-center"><div class="profile-overview panel"><button type="button" class="profile-portrait" data-broke="settings" aria-label="${t("Open user settings","Mở cài đặt người dùng","사용자 설정 열기")}" title="${t("User settings","Cài đặt người dùng","사용자 설정")}">${currentAccount.photo?`<img class="profile-account-photo" src="${e(currentAccount.photo)}" alt="${t("Profile picture","Ảnh đại diện","프로필 사진")}">`:`<span>${e((accountName||profile.name).charAt(0))}</span>`}<b aria-hidden="true">✦</b></button><div class="profile-identity"><div class="profile-name-row"><h1 id="broke-title" tabindex="-1">${e(accountName||profile.name)}</h1></div><p>${e(profileBio())}</p></div><div class="profile-metric"><span>♡</span><div><small>${t("Total commitments","Tổng cam kết","총 지원 약속")}</small><strong>${cash(pledged)}</strong></div></div><div class="profile-metric"><span>♧</span><div><small>${t("My stories","Câu chuyện của tôi","내 이야기")}</small><strong>${t(`${posts.length} ${posts.length===1?'story':'stories'}`,`${posts.length} câu chuyện`,`이야기 ${posts.length}개`)}</strong></div></div></div><section class="gratitude panel"><div class="panel-heading"><div><h2><span>♡</span> ${t("Wall of Gratitude","Góc tri ân","감사의 벽")}</h2><p>${t("The ones who stood by me when it mattered most.","Những người đã ở bên tôi lúc tôi cần nhất.","가장 힘들 때 곁을 지켜준 사람들.")}</p></div></div><div class="gratitude-demo-label">${t("DEMO VIEW · NO ACTUAL SUPPORT RECEIVED","GIAO DIỆN MINH HỌA · CHƯA CÓ HỖ TRỢ THẬT","예시 화면 · 실제 지원 내역 없음")}</div><div class="supporter-marquee"><div class="supporter-track"><div class="supporter-grid">${[['CW','@CryptoWhale',t("Top Supporter","Người hỗ trợ hàng đầu","최고 후원자"),'12.000.000 ₫',t("Keep going! 💪","Cố lên nhé! 💪","힘내세요! 💪"),'gold'],['TL','@QuyTamLong',t("Kind Supporter","Người hỗ trợ tận tâm","따뜻한 후원자"),'6.500.000 ₫',t("You can do it! 🌱","Bạn làm được mà! 🌱","해낼 수 있어요! 🌱"),'pink'],['DB','@DiamondBro_VN',t("Early Supporter","Người hỗ trợ đầu tiên","초기 후원자"),'5.000.000 ₫',t("Always here for you.","Mình luôn ở đây vì bạn.","언제나 곁에 있을게요."),'blue']].map(([initial,name,badge,amount,message,color])=>`<article class="supporter ${color}" role="button" tabindex="0" data-supporter-name="${name}" data-supporter-initials="${initial}" data-supporter-color="${color}" aria-label="${t(`Message ${name}`,`Nhắn tin với ${name}`,`${name}님에게 메시지 보내기`)}"><div class="supporter-person"><div class="supporter-avatar">${initial}</div><div><strong>${name}</strong><small>${color==='gold'?'♛':'♡'} ${badge}</small></div></div><b>+${amount}</b><p>“${message}”</p><span class="sample-tag">${t("Sample","Mẫu","예시")}</span></article>`).join('')}</div></div></div><div class="gratitude-foot"><span>${t("Every kindness deserves to be remembered.","Mỗi việc tử tế đều xứng đáng được ghi nhớ.","모든 친절은 기억할 가치가 있습니다.")}</span></div></section><section class="journey-banner"><div><h2>${t("Never Taken for Granted.","Không bao giờ xem là điều hiển nhiên.","어떤 도움도 당연하지 않습니다.")}</h2><p>${t("Every kindness counts.","Mọi sự tử tế đều đáng quý.","모든 친절이 소중합니다.")}</p></div></section><div class="broke-shortcuts">${[['♙',t("My Profile","Hồ sơ của tôi","내 프로필"),'edit'],['▤',t("My Stories","Câu chuyện của tôi","내 이야기"),'posts'],['◎',t("My Goals","Mục tiêu của tôi","내 목표"),'goal'],['◷',t("Activity","Hoạt động","활동"),'activity'],['＋',t("Share Story","Chia sẻ câu chuyện","이야기 공유"),'post'],['♡',t("Say Thanks","Gửi lời cảm ơn","감사 전하기"),'thanks']].map(([icon,title,action])=>`<button data-broke="${action}"><span>${icon}</span>${title}</button>`).join('')}</div><section class="journey-detail panel"><div class="journey-tabs"><button data-broke="journey" class="${tab==='journey'?'selected':''}">${t("▥ My Journey","▥ Hành trình của tôi","▥ 내 여정")}</button><button data-broke="activity" class="${tab==='activity'?'selected':''}">${t("◷ Activity","◷ Hoạt động","◷ 활동")}</button></div>${tab==='journey'?`<div class="journey-body"><div><span class="broke-eyebrow">${t("ONE DAY AT A TIME","TỪNG NGÀY MỘT","하루하루 한 걸음씩")}</span><h3>${t("Your next chapter starts here.","Chương mới của bạn bắt đầu từ đây.","여기서 새로운 시작을.")}</h3><p>${t("Track your progress, set achievable goals and share your story when you’re ready.","Ghi lại tiến độ của chính bạn, đặt mục tiêu vừa sức và chia sẻ câu chuyện khi bạn sẵn sàng.","진행 상황을 기록하고 달성할 수 있는 목표를 세우세요. 준비가 되면 이야기를 공유해 보세요.")}</p><button class="broke-primary" data-broke="goal">${t("Update my journey ↗","Cập nhật hành trình ↗","내 여정 업데이트 ↗")}</button></div><div class="journey-summary"><div><span>${t("Self-reported repayments","Đã tự ghi nhận trả","직접 기록한 상환액")}</span><strong>${cash(profile.paid)}</strong></div><div><span>${t("Community pledges","Cam kết từ cộng đồng","커뮤니티 지원 약속")}</span><strong>${cash(pledged)}</strong></div><small>${t("Pledges are separate from money received. You track your own progress.","Cam kết chưa phải tiền đã nhận. Tiến độ do bạn tự cập nhật.","지원 약속은 실제로 받은 금액과 별개입니다. 진행 상황은 직접 업데이트합니다.")}</small></div></div>`:`<div class="activity-list">${posts.length?posts.map(p=>`<div><span class="activity-icon">▤</span><div><strong>${e(p.title)}</strong><p>${t(`Debt ${cash(p.amount)} · Pledged ${cash(p.pledged)}`,`Khoản nợ ${cash(p.amount)} · Cam kết ${cash(p.pledged)}`,`채무 ${cash(p.amount)} · 지원 약속 ${cash(p.pledged)}`)}</p></div><button data-broke="posts" aria-label="${t("View post","Xem bài đăng","게시물 보기")}">↗</button></div>`).join(''):'<div><span class="activity-icon">🌱</span><div><strong>'+t("A fresh start awaits.","Một khởi đầu mới đang chờ bạn.","새로운 시작이 기다립니다.")+'</strong><p>'+t("No posts yet. Share your first story.","Chưa có bài đăng. Chia sẻ câu chuyện đầu tiên của bạn.","게시물이 없습니다. 첫 이야기를 공유해 보세요.")+'</p></div><button data-broke="post" aria-label="'+t("Create post","Tạo bài đăng","게시물 작성")+'">＋</button></div>'}${profile.thanks?`<div><span class="activity-icon">♡</span><div><strong>${t("Your thank-you note · Private draft","Lời cảm ơn của bạn · bản nháp riêng tư","내 감사 메시지 · 비공개 초안")}</strong><p>${e(profile.thanks)}</p></div></div>`:''}</div>`}</section><p class="broke-disclaimer">${t("Payments are unavailable in this preview. Your profile and progress are saved only in this browser.","Không có thanh toán trong bản thử nghiệm. Hồ sơ và tiến độ chỉ được lưu trên trình duyệt này.","미리보기에서는 결제할 수 없습니다. 프로필과 진행 상황은 이 브라우저에만 저장됩니다.")}</p></div><div class="broke-right"><section class="profile-primary-actions"><button data-broke="discover"><span aria-hidden="true">◈</span><strong>${t("Discover Broke","Tìm Broke","Broke 둘러보기")}</strong><b aria-hidden="true">↗</b></button><button data-broke="create-card"><span aria-hidden="true">＋</span><strong>${t("Create a debt card","Tạo thẻ báo nợ","채무 카드 만들기")}</strong><b aria-hidden="true">↗</b></button></section><section class="quote-card"><div><span>“</span><blockquote>${t("A friend in need","Bạn bè lúc hoạn nạn","어려울 때 곁에 있는 사람이")}<br>${t("is a friend indeed.","mới là bạn thật sự.","진정한 친구입니다.")}</blockquote><i></i><img src="assets/debtfreelately-logo-transparent.png" alt="DebtFreeLately"></div></section><div class="gentle-note"><span>♧</span><p>${t("You are more than your debt.","Bạn đáng giá hơn khoản nợ của mình.","당신의 가치는 빚으로 정해지지 않습니다.")}<br><strong>${t("And you don't have to do this alone.","Và bạn không phải đi một mình.","그리고 혼자 감당할 필요는 없습니다.")}</strong></p></div></div></div>`;startSupporterMarquee();}
function edit(){api.modal(`<div class="eyebrow">${t("MY PROFILE & JOURNEY","HỒ SƠ &amp; HÀNH TRÌNH CỦA TÔI","내 프로필과 여정")}</div><h2>${t("A fresh start, your way.","Một khởi đầu mới theo cách của bạn.","나만의 방식으로 새롭게 시작하세요.")}</h2><form id="broke-profile-form"><label for="bp-name">${t("Display name or nickname","Tên hiển thị / biệt danh","표시 이름 또는 닉네임")}</label><input id="bp-name" name="name" maxlength="50" required value="${e(profile.name)}"><label for="bp-bio">${t("Short bio","Giới thiệu ngắn","짧은 자기소개")}</label><input id="bp-bio" name="bio" maxlength="120" value="${e(profileBio())}"><label for="bp-goal">${t("Total repayment goal (VND)","Tổng mục tiêu trả nợ (VNĐ)","총 상환 목표(VND)")}</label><input id="bp-goal" name="goal" type="number" min="1000" max="1000000000000" step="1000" required value="${profile.goal}"><label for="bp-paid">${t("Self-reported repayments (VND)","Đã trả — do bạn tự ghi nhận (VNĐ)","직접 기록한 상환액(VND)")}</label><input id="bp-paid" name="paid" type="number" min="0" max="1000000000000" step="1000" required value="${profile.paid}"><label for="bp-next">${t("Next goal","Mục tiêu tiếp theo","다음 목표")}</label><input id="bp-next" name="next" maxlength="140" value="${e(profileNext())}"><div class="info-box">${t("This is a personal journal. It does not verify or process payments.","Đây là nhật ký cá nhân, không xác nhận hoặc thực hiện thanh toán.","개인 기록용입니다. 결제를 확인하거나 처리하지 않습니다.")}</div><div class="form-error" id="bp-error" role="alert"></div><button class="dark">${t("Save profile","Lưu hồ sơ","프로필 저장")}</button></form>`);document.querySelector('#broke-profile-form').onsubmit=ev=>{ev.preventDefault();const d=Object.fromEntries(new FormData(ev.target));d.goal=Number(d.goal);d.paid=Number(d.paid);d.name=d.name.trim();if(!d.name||!Number.isFinite(d.goal)||d.goal<1000||d.goal>1e12||!Number.isFinite(d.paid)||d.paid<0||d.paid>d.goal){document.querySelector('#bp-error').textContent=t("Enter a valid name and amounts. Repayments cannot exceed your goal.","Vui lòng điền tên và số tiền hợp lệ; số đã trả không vượt mục tiêu.","올바른 이름과 금액을 입력하세요. 상환액은 목표 금액을 넘을 수 없습니다.");return;}if(d.bio===profileBio())d.bio=profile.bio;if(d.next===profileNext())d.next=profile.next;profile={...profile,...d};write();api.close();render();api.toast(t("Profile and progress saved on this device.","Đã lưu hồ sơ và tiến độ trên thiết bị.","이 기기에 프로필과 진행 상황을 저장했습니다."));};}
function thanks(){api.modal(`<div class="eyebrow">${t("A LITTLE GRATITUDE","MỘT CHÚT BIẾT ƠN","감사의 마음")}</div><h2>${t("Every kindness counts.","Mọi sự tử tế đều đáng quý.","모든 친절이 소중합니다.")}</h2><p>${t("Write a thank-you note for those who have supported you. The preview saves it privately on this device without sending it.","Viết một lời cảm ơn cho những người đã đồng hành. Bản thử nghiệm chỉ lưu riêng tư trên thiết bị, chưa gửi cho người khác.","함께해 준 사람들에게 감사 메시지를 써 보세요. 미리보기에서는 메시지가 전송되지 않고 이 기기에만 비공개로 저장됩니다.")}</p><form id="broke-thanks"><label for="thanks-note">${t("Your thank-you note","Lời cảm ơn của bạn","내 감사 메시지")}</label><textarea id="thanks-note" name="note" maxlength="1000" required>${e(profile.thanks)}</textarea><button class="dark">${t("Save private thank-you note","Lưu lời cảm ơn riêng tư","감사 메시지를 비공개로 저장")}</button></form>`);document.querySelector('#broke-thanks').onsubmit=ev=>{ev.preventDefault();const note=new FormData(ev.target).get('note').trim();if(!note)return;profile.thanks=note;write();api.close();tab='activity';render();api.toast(t("Draft saved. It has not been sent to anyone.","Đã lưu bản nháp. Chưa gửi cho người khác.","초안을 저장했습니다. 다른 사람에게 전송되지 않았습니다."));};}
function supporters(){api.modal('<div class="eyebrow">'+t("MY SUPPORTERS","NHỮNG NGƯỜI HỖ TRỢ TÔI","내 후원자")+'</div><h2>'+t("A little help goes a long way.","Một chút giúp đỡ tạo nên thay đổi lớn.","작은 도움이 큰 힘이 됩니다.")+'</h2><p>'+t("You don’t have any confirmed supporters yet. The cards on the Wall of Gratitude are samples.","Bạn chưa có người hỗ trợ được xác nhận. Các thẻ trên Wall of Gratitude là dữ liệu minh họa thiết kế.","확인된 후원자가 아직 없습니다. 감사의 벽에 있는 카드는 예시입니다.")+'</p><div class="info-box">'+t("Real supporters will appear once accounts, shared data and payments are connected.","Danh sách hỗ trợ thật sẽ được kết nối khi có tài khoản, dữ liệu dùng chung và hệ thống thanh toán.","계정, 공유 데이터 및 결제 시스템이 연결되면 실제 후원자가 표시됩니다.")+'</div>');}




function startSupporterMarquee(){const track=document.querySelector('#broke-dashboard .supporter-track'),group=track?.querySelector('.supporter-grid');if(!group)return;for(const card of [...group.children]){const repeat=card.cloneNode(true);repeat.setAttribute('aria-hidden','true');repeat.tabIndex=-1;group.append(repeat);}const clone=group.cloneNode(true);clone.setAttribute('aria-hidden','true');clone.querySelectorAll('[data-supporter-name]').forEach(card=>card.tabIndex=-1);track.append(clone);}








